class Solution {
public:
    int rearrangeCharacters(string s, string target) {
        int cnt[26] = {0};
        int tcnt[26] = {0};
        for (char c : s) cnt[c - 'a']++;
        for (char c : target) tcnt[c - 'a']++;
        int ans = INT_MAX;
        for (int i = 0; i < 26; i++) {
            if (tcnt[i] > 0) {
                ans = min(ans, cnt[i] / tcnt[i]);
            }
        }
        return ans == INT_MAX ? 0 : ans;
    }
};
